// A2 stories (10). Generated from the writers' study pack. Format: id,t,l,cat,pron,e,min,s=[[de,en]],v=[[word,grammar,meaning]],qs=[{q,o,a,e}].
(window.NEWSTORY=window.NEWSTORY||[]).push(...[{"id":"A2-1","t":"Eine Wohnung suchen","l":"A2","cat":"Housing & Viewing an Apartment","pron":"Note the glottal stop between prefixes and stems: an-melden [ˈanˌmɛldn̩], be-sichtigen [bəˈzɪçtɪɡn̩]. Compound nouns carry primary stress on the first root: Mietvertrag, Wohnungsbesichtigung.","e":"🏠","min":1,"s":[["Lukas suchte schon seit drei Monaten eine bezahlbare Wohnung in Köln, weil sein alter Mietvertrag bald endete.","Lukas had already been looking for an affordable apartment in Cologne for three months because his old lease was ending soon."],["Gestern hat er endlich eine Einladung zu einer Wohnungsbesichtigung bekommen.","Yesterday, he finally received an invitation to an apartment viewing."],["Die Wohnung liegt im dritten Stock eines gepflegten Altbaus in der Südstadt.","The apartment is located on the third floor of a well-maintained period building in the Südstadt."],["Als Lukas ankam, musste er sich zuerst bei der Maklerin vorstellen.","When Lukas arrived, he first had to introduce himself to the real estate agent."],["Er hat sich sehr gefreut, dass das Wohnzimmer helle Fenster und einen schönen Holzboden hatte.","He was very pleased that the living room had bright windows and a beautiful wooden floor."],["Im Flur stellte er seine Tasche auf den Boden und sah sich aufmerksam um.","In the hallway, he placed his bag on the floor and looked around attentively."],["Die Maklerin erklärte, dass die Nebenkosten bereits in der Warmmiete enthalten sind.","The agent explained that utilities were already included in the warm rent."],["Lukas fragte vorsichtig, ob Haustiere im Haus erlaubt sind, weil er eine Katze hat.","Lukas asked cautiously whether pets were permitted in the building because he has a cat."],["Die Vermieterin lächelte und antwortete, dass eine kleine Katze kein Problem sei.","The landlady smiled and answered that a small cat would be no problem."],["Lukas hat die erforderlichen Unterlagen sofort auf den Tisch gelegt.","Lukas immediately put the required documents onto the table."],["Er hofft nun, dass er den Zuschlag für diese schöne Wohnung bekommt.","He now hopes that he will get the contract for this beautiful apartment."]],"v":[["suchte / endete","Präteritum","Simple past of suchen and enden. In written narratives, simple past is common for narrative background."],["hat bekommen / hat gefreut","Perfekt","Conversational past formed with auxiliary haben + past participle (Partizip II)."],["weil sein alter Mietvertrag bald endete","","Subordinating conjunction weil (because) kicks the finite verb endete to the absolute end of the clause."],["liegt im dritten Stock","Dative","Two-way preposition in + masculine dative (in dem = im), answering the question Wo? (location)."],["musste sich vorstellen","","Modal verb müssen in Präteritum combined with the reflexive verb sich vorstellen (to introduce oneself)."],["dass das Wohnzimmer helle Fenster ... hatte","","Subordinating conjunction dass (that) triggers verb-final position (hatte)."],["stellte auf den Boden","Accusative","Two-way preposition auf + masculine accusative (den Boden), indicating directional motion (Wohin?)."],["die Warmmiete","Noun, f.","Total rent including utility costs and heating, contrasting with Kaltmiete (base rent)."],["ob Haustiere ... erlaubt sind","","Indirect question introduced by ob (whether/if) with verb-final word order."],["hat ... gelegt","Perfekt","Weak verb legen (to lay/place horizontally), requiring an accusative object (die Unterlagen) and directional complement."]],"qs":[{"q":"Warum brauchte Lukas dringend eine neue Wohnung?","o":["Er wollte in ein anderes Land umziehen.","Sein alter Mietvertrag ging bald zu Ende.","Seine Wohnung war viel zu groß.","Er hatte Streit mit seinen Nachbarn."],"a":1,"e":"Der Text besagt: „... weil sein alter Mietvertrag bald endete.“ Weil leitet einen Kausalnebensatz ein und begründet den Wohnungswechsel."},{"q":"Was gefiel Lukas besonders gut am Wohnzimmer?","o":["Die neuen Möbel und der Teppich.","Der große Balkon mit Gartenblick.","Die hellen Fenster und der Holzboden.","Die weiße Wandfarbe und die moderne Lampe."],"a":2,"e":"Im Text heißt es explizit: „Er hat sich sehr gefreut, dass das Wohnzimmer helle Fenster und einen schönen Holzboden hatte.“"},{"q":"Wohin stellte Lukas seine Tasche während der Besichtigung?","o":["In die Küche auf den Tisch.","Auf das Sofa im Wohnzimmer.","Vor die Haustür im Treppenhaus.","Auf den Boden im Flur."],"a":3,"e":"Textbeleg: „Im Flur stellte er seine Tasche auf den Boden ...“ Die Wechselpräposition auf steht hier mit Akkusativ (den Boden), da eine Richtungsbewegung vorliegt."},{"q":"Warum erkundigte sich Lukas nach Haustieren?","o":["Weil er zwei Hunde mitbringen wollte.","Weil er eine Katze besitzt.","Weil er im Tierheim arbeitet.","Weil er Angst vor Hunden im Haus hat."],"a":1,"e":"Der Text erklärt: „Lukas fragte vorsichtig, ob Haustiere im Haus erlaubt sind, weil er eine Katze hat.“"}],"_src":"Housing & Viewing an Apartment (astrovi888.github.io A2)"},{"id":"A2-2","t":"Das verschwundene Fahrrad am Bahnhof","l":"A2","cat":"Daily Commute & Police Report (/ )","pron":"Emphasize the separable prefixes in verbs: abschließen [ˈapʃliːsn̩], anzeigen [ˈanˌtsaɪ̯ɡn̩]. Watch the difference between unvoiced /s/ in Polizist and voiced /z/ in suchen.","e":"🚆","min":1,"s":[["Jeden Morgen fährt Jonas mit seinem grünen Fahrrad zum Hauptbahnhof, weil er mit dem Zug zur Universität pendelt.","Every morning Jonas rides his green bicycle to the central station because he commutes to university by train."],["Er schloss das Rad immer sorgfältig an einem massiven Metallgitter ab.","He always locked the bike carefully to a solid metal railing."],["Doch gestern Abend hat er sein Fahrrad nicht mehr am gewohnten Platz gefunden.","But yesterday evening, he no longer found his bicycle at the usual spot."],["Er hat sich sofort sehr geärgert, weil das Fahrrad neu und ziemlich teuer war.","He immediately felt very annoyed because the bike was new and quite expensive."],["Zuerst suchte er auf dem gesamten Bahnhofsvorplatz, aber es war spurlos verschwunden.","First, he searched the entire station forecourt, but it had vanished without a trace."],["Jonas wollte den Vorfall nicht einfach ignorieren, deshalb ging er direkt zur Polizeiwache am Bahnhof.","Jonas did not want to simply ignore the incident, so he went straight to the police station at the train station."],["Ein freundlicher Polizist hat den Diebstahl sofort aufgenommen.","A friendly police officer immediately recorded the theft."],["Jonas erklärte genau, dass das Fahrrad einen auffälligen schwarzen Sattel und silberne Schutzbleche hat.","Jonas explained precisely that the bicycle had a conspicuous black saddle and silver mudguards."],["Der Beamte fragte, ob Jonas die Rahmennummer des Fahrrads noch wisse.","The officer asked whether Jonas still knew the bike’s frame number."],["Glücklicherweise hatte Jonas ein Foto von der Rechnung auf seinem Smartphone gespeichert.","Fortunately, Jonas had saved a photo of the receipt on his smartphone."],["Der Polizist versprach, dass die Polizei die Überwachungskameras überprüfen wird.","The officer promised that the police would check the surveillance cameras."]],"v":[["fährt","Präsens, Vokalwechsel","Irregular verb fahren (a -> ä in 2nd/3rd person singular: er fährt)."],["schloss ... ab","Präteritum, trennbar","From abschließen (to lock). Separable prefix ab shifts to clause end in the main clause."],["hat ... gefunden","Perfekt","Strong verb finden forms participle gefunden with root vowel change (i -> u)."],["hat sich geärgert","Reflexiv, Perfekt","Sich ärgern über (+ Akk.). Reflexive pronoun sich matches 3rd person singular."],["wollte","Präteritum Modalverb","Simple past of wollen (ich/er wollte), indicating past intention."],["deshalb ging er","","Inverted word order after adverbial connector deshalb (consequence: verb occupies position 2)."],["hat ... aufgenommen","Perfekt, trennbar","Strong verb aufnehmen (to record/register) -> hat aufgenommen."],["dass das Fahrrad ... hat","","Conjunction dass forces the verb hat to the end."],["ob Jonas ... wisse","","Conjunction ob introduces indirect questions, keeping the verb at the clause end."],["auf seinem Smartphone","Dativ","Two-way preposition auf with neuter dative (seinem Smartphone) indicates static location (Wo?)."]],"qs":[{"q":"Warum stellt Jonas sein Fahrrad jeden Tag am Hauptbahnhof ab?","o":["Er wohnt direkt neben dem Bahnhof.","Er pendelt mit dem Zug zur Universität.","Er arbeitet als Mechaniker am Bahnhof.","Er trifft dort jeden Morgen seine Freunde."],"a":1,"e":"Im Text steht: „... weil er mit dem Zug zur Universität pendelt.“ Die Konjunktion weil liefert den Grund für die tägliche Fahrt zum Bahnhof."},{"q":"Wie reagierte Jonas, als sein Fahrrad verschwunden war?","o":["Er kaufte sich sofort ein neues Ticket.","Er fuhr mit dem Bus nach Hause.","Er suchte auf dem Vorplatz und ging zur Polizei.","Er rief seine Eltern an, damit sie ihn abholen."],"a":2,"e":"Jonas suchte zuerst auf dem Platz und ging anschließend zur Wache: „Zuerst suchte er auf dem gesamten Bahnhofsvorplatz ... deshalb ging er direkt zur Polizeiwache ...“"},{"q":"Welche Besonderheiten hatte das Fahrrad laut Jonas?","o":["Einen roten Korb und ein blaues Licht.","Einen schwarzen Sattel und silberne Schutzbleche.","Gelbe Reifen und eine laute Klingel.","Eine grüne Kette und keinen Sattel."],"a":1,"e":"Der Text bestätigt: „Jonas erklärte genau, dass das Fahrrad einen auffälligen schwarzen Sattel und silberne Schutzbleche hat.“"},{"q":"Warum konnte Jonas der Polizei wichtige Angaben machen?","o":["Er hatte die Rahmennummer auf den Arm geschrieben.","Er besaß ein Foto der Quittung auf seinem Handy.","Der Dieb hatte seine Visitenkarte verloren.","Die Kamera hatte den Dieb direkt fotografiert."],"a":1,"e":"Jonas war vorbereitet: „Glücklicherweise hatte Jonas ein Foto von der Rechnung auf seinem Smartphone gespeichert.“ Auf Rechnungen steht üblicherweise die Rahmennummer."}],"_src":"Daily Commute & Police Report (Inklingo / Lenguia A2)"},{"id":"A2-3","t":"Die Geigensaite beim Konzert in Weimar","l":"A2","cat":"Music & Performance ()","pron":"Distinct pronunciation of diphthongs: Geige [ˈɡaɪ̯ɡə], Saite [ˈzaɪ̯tə]. Pay attention to terminal devoicing (Auslautverhärtung): Konzert [kɔnˈtsɛʁt], Stadt [ʃtat].","e":"🎻","min":1,"s":[["Clara studierte Musikhochschule in Weimar und durfte gestern ihr erstes großes Solo spielen.","Clara was studying at the music academy in Weimar and was allowed to play her first big solo yesterday."],["Viele Besucher saßen im festlich beleuchteten Saal, weil das Orchester berühmt war.","Many visitors were sitting in the festively lit hall because the orchestra was famous."],["Clara hat sich monatelang auf diesen wichtigen Abend vorbereitet.","Clara had prepared for this important evening for months."],["Als sie die Bühne betrat, stellte sie sich ruhig neben das Notenpult.","When she entered the stage, she positioned herself calmly next to the music stand."],["Sie begann ihr Stück mit geschlossenen Augen, und die Melodie klang wunderbar durch den Raum.","She began her piece with closed eyes, and the melody sounded wonderful throughout the room."],["Doch mitten im zweiten Satz ist plötzlich eine Saite ihrer Geige mit einem lauten Ton gerissen.","But in the middle of the second movement, a string of her violin suddenly snapped with a loud sound."],["Das Publikum hielt überrascht den Atem an, weil niemand mit einem Unfall gerechnet hatte.","The audience held its breath in surprise because no one had counted on an accident."],["Clara musste sich schnell entscheiden, wie sie reagieren sollte.","Clara had to decide quickly how she should react."],["Sie hat nicht aufgehört, sondern spielte das schwierige Stück auf den anderen drei Saiten zu Ende.","She did not stop, but finished playing the difficult piece on the other three strings."],["Nach dem letzten Ton stand der ganze Saal auf und applaudierte begeistert.","After the last note, the entire hall stood up and applauded enthusiastically."],["Clara hat sich tief verbeugt, weil sie sehr stolz auf ihren Mut war.","Clara bowed deeply because she was very proud of her courage."]],"v":[["durfte spielen","Modalverb Präteritum","Dürfen expresses permission (sie durfte = she was allowed to)."],["saßen","Präteritum","Strong verb sitzen -> saßen. Describes ongoing state in the past."],["hat sich vorbereitet","Reflexiv + Trennbar","Sich vorbereiten auf (+ Akk.). Prefix vor- precedes participle base: vor-ge-baut / vor-ge-richtet / vor-ge-leistet -> vorbereitet."],["stellte sich neben","Akkusativ","Two-way preposition neben with accusative reflexive pronoun (sich) indicating target position."],["begann","Präteritum","Irregular strong verb beginnen -> begann -> hat begonnen."],["ist gerissen","Perfekt mit sein","Intransitive verb expressing change of physical state (reißen) forms Perfekt with sein (ist gerissen)."],["hielt den Atem an","Präteritum, trennbar","Idiomatic expression den Atem anhalten (to hold one's breath)."],["musste sich entscheiden","Reflexiv mit Modalverb","Modal verb musste pushes the reflexive infinitive sich entscheiden to the end."],["hat nicht aufgehört","Perfekt, trennbar","Aufhören (to stop/cease) takes haben + aufgehört."],["stolz auf","Präpositionaladjektiv","Adjective taking preposition auf + accusative (stolz auf ihren Mut)."]],"qs":[{"q":"Welches Ereignis fand gestern in Weimar statt?","o":["Ein Musikwettbewerb für Schulkinder.","Claras erstes großes Solo im Konzertsaal.","Eine feierliche Eröffnung einer neuen Schule.","Eine Probe ohne Zuschauer."],"a":1,"e":"Der einleitende Satz stellt fest: „Clara ... durfte gestern ihr erstes großes Solo spielen.“"},{"q":"Was passierte während des zweiten Satzes der Musik?","o":["Die Noten fielen vom Pult.","Das Licht im Saal ging plötzlich aus.","Eine Saite an Claras Violine riss entzwei.","Der Dirigent verließ überraschend die Bühne."],"a":2,"e":"Der Wendepunkt im Text lautet: „... ist plötzlich eine Saite ihrer Geige mit einem lauten Ton gerissen.“"},{"q":"Wie löste Clara die schwierige Situation auf der Bühne?","o":["Sie verließ weinend den Konzertsaal.","Sie bat einen anderen Geiger um sein Instrument.","Sie spielte das Musikstück auf den restlichen Saiten zu Ende.","Sie begann das gesamte Musikstück noch einmal von vorn."],"a":2,"e":"Die Handlungsauflösung zeigt Claras Können: „Sie hat nicht aufgehört, sondern spielte das schwierige Stück auf den anderen drei Saiten zu Ende.“"},{"q":"Wie reagierten die Zuschauer am Ende des Auftritts?","o":["Sie verließen den Saal vollkommen schweigend.","Sie standen auf und spendeten enthusiastischen Beifall.","Sie lachten laut über das Missgeschick.","Sie verlangten sofort ihr Geld zurück."],"a":1,"e":"Am Ende steht: „Nach dem letzten Ton stand der ganze Saal auf und applaudierte begeistert.“ Aufstehen und begeistert applaudieren drückt Standing Ovations aus."}],"_src":"Music & Performance (Inklingo Series)"},{"id":"A2-4","t":"Die Treppe in Trier, die laut Stadtplan nicht existiert","l":"A2","cat":"Travel & Discovery ()","pron":"Note short vs. long vowels: Stadt [ʃtat] (short /a/) vs. Plan [plaːn] (long /aː/). The cluster kt in existiert must be articulated cleanly: [ɛksɪsˈtiːɐ̯t].","e":"🪜","min":1,"s":[["David reiste am Wochenende nach Trier, weil er die berühmten römischen Bauwerke besichtigen wollte.","David traveled to Trier at the weekend because he wanted to visit the famous Roman monuments."],["Am Nachmittag holte er einen modernen Stadtplan aus der Touristeninformation.","In the afternoon, he picked up a modern city map from the tourist information office."],["Er spazierte durch die engen Gassen hinter dem Dom, wo nur wenige Touristen unterwegs waren.","He strolled through the narrow alleys behind the cathedral, where only a few tourists were on the go."],["Plötzlich stand er vor einer alten, moosbewachsenen Steintreppe, die steil nach oben führte.","Suddenly he stood before an old, moss-covered stone staircase that led steeply upward."],["David schaute sofort auf seinen Stadtplan, aber an dieser Stelle war nur eine durchgehende Mauer eingezeichnet.","David immediately looked at his map, but at this spot only a solid wall was drawn."],["Er hat sich sehr gewundert, warum diese Treppe nirgendwo verzeichnet war.","He wondered very much why this staircase was recorded nowhere."],["Neugierig stieg er Stufe für Stufe hinauf, bis er auf eine kleine, sonnige Terrasse gelangte.","Curiously, he climbed step by step until he reached a small, sunny terrace."],["Von dort hatte man einen atemberaubenden Blick über die gesamte Altstadt und die Mosel.","From there, one had a breathtaking view over the entire old town and the Moselle."],["David hat sich auf eine Steinbank gesetzt und den Ausblick genossen.","David sat down on a stone bench and enjoyed the view."],["Als er später einen Einheimischen traf, erfuhr er, dass die Treppe vor zweihundert Jahren von Mönchen gebaut worden war.","When he later met a local, he learned that the staircase had been built by monks two hundred years ago."]],"v":[["reiste / spazierte","Präteritum, schwach","Regular weak verbs forming Präteritum with -te (reiste, spazierte)."],["besichtigen wollte","Modalverbklammer","Dependent infinitive besichtigen precedes conjugated modal auxiliary wollte at clause end."],["holte aus der Information","Dativ","Preposition aus always demands the dative case (der Information, f.)."],["stand vor einer Treppe","Dativ","Two-way preposition vor indicating stationary location (Wo stand er? -> vor einer alten Steintreppe)."],["hat sich gewundert","Reflexiv Perfekt","Sich wundern über (+ Akk.) -> hat sich gewundert."],["war verzeichnet","Zustandspassiv","Auxiliary sein + participle II expresses a completed condition/state."],["stieg hinauf","Präteritum, trennbar","Strong verb steigen (stieg) combined with directional adverb hinauf."],["hat sich gesetzt","Reflexiv Perfekt, Akkusativ","Directional action of sitting down (sich auf die Bank setzen)."],["erfuhr","Präteritum","Irregular strong verb erfahren (to learn/find out something) -> erfuhr."],["dass die Treppe ... gebaut worden war","Plusquamperfekt Passiv","Subordinate clause indicating an action occurring prior to the meeting."]],"qs":[{"q":"Aus welchem Grund besuchte David die Stadt Trier?","o":["Er wollte alte Freunde aus der Schulzeit treffen.","Er wollte die bekannten römischen Sehenswürdigkeiten ansehen.","Er musste geschäftlich an einer Konferenz teilnehmen.","Er suchte nach einer Wohnung in der Nähe der Mosel."],"a":1,"e":"Der Eröffnungssatz erklärt die Absicht: „... weil er die berühmten römischen Bauwerke besichtigen wollte.“"},{"q":"Was bemerkte David auf seinem offiziellen Stadtplan?","o":["Der Plan zeigte falsche Straßennamen.","Die gefundene Steintreppe war im Plan überhaupt nicht eingezeichnet.","Die Altstadt war viel kleiner als in der Realität.","Der Dom war auf der falschen Seite eingezeichnet."],"a":1,"e":"Der Text verdeutlicht: „... aber an dieser Stelle war nur eine durchgehende Mauer eingezeichnet. Er hat sich sehr gewundert, warum diese Treppe nirgendwo verzeichnet war.“"},{"q":"Was entdeckte David, als er die Treppe hinaufstieg?","o":["Ein altes römisches Tor aus rotem Sandstein.","Ein verstecktes Café ohne Gäste.","Eine sonnige Terrasse mit wunderschönem Panoramablick.","Eine verschlossene Eisentür mit einem großen Schloss."],"a":2,"e":"Das Ziel des Aufstiegs: „... bis er auf eine kleine, sonnige Terrasse gelangte. Von dort hatte man einen atemberaubenden Blick über die gesamte Altstadt ...“"},{"q":"Welches Detail erfuhr David später von einem Bürger der Stadt?","o":["Dass römische Soldaten die Treppe gebaut hatten.","Dass Mönche die Treppe vor 200 Jahren angelegt hatten.","Dass die Stadtverwaltung die Treppe bald abreißen will.","Dass dort oben ein Schatz versteckt liegt."],"a":1,"e":"Zum geschichtlichen Hintergrund: „... erfuhr er, dass die Treppe vor zweihundert Jahren von Mönchen gebaut worden war.“"}],"_src":"Travel & Discovery (Inklingo Series)"},{"id":"A2-5","t":"Das Trikot, das die Mannschaft nie wusch","l":"A2","cat":"Sports & Superstition ()","pron":"Watch the open short /ʊ/ sound in words like wusch [vʊʃ] (irregular Präteritum of waschen). The trigraph sch is always pronounced [ʃ]. Note the stress on the compound noun: Mannschaft [ˈmanʃaft].","e":"⚽","min":1,"s":[["Der FC Neustadt hatte vor fünf Jahren das wichtigste Spiel der Vereinsgeschichte gewonnen.","FC Neustadt had won the most important match in the club’s history five years ago."],["In diesem Finale trug der Kapitän Marco ein rotes Trikot mit der Nummer zehn.","In this final, team captain Marco wore a red jersey with number ten."],["Weil die Mannschaft nach dem Sieg sehr abergläubisch wurde, durfte die Zeugwartin das Trikot niemals in die Waschmaschine stecken.","Because the team became very superstitious after the victory, the kit manager was never allowed to put the jersey into the washing machine."],["Das Kleidungsstück blieb ungewaschen und wurde in einer Vitrine im Vereinsheim aufbewahrt.","The piece of clothing remained unwashed and was kept in a display case in the clubhouse."],["Vor jedem Meisterschaftsspiel mussten alle Spieler das Trikot mit der rechten Hand berühren, damit sie Glück hatten.","Before every championship match, all players had to touch the jersey with their right hand so that they would have good luck."],["Viele neue Mitglieder haben sich oft darüber gewundert, weil das Ritual sehr seltsam schien.","Many new members frequently wondered about this because the ritual seemed very strange."],["Gestern Abend hat ein neuer Trainer die Mannschaft übernommen.","Yesterday evening, a new coach took over the team."],["Als er die alte Vitrine sah, fragte er erstaunt, warum das schmutzige Hemd dort hing.","When he saw the old glass case, he asked in astonishment why the dirty shirt hung there."],["Die Spieler erklärten ihm geduldig, dass dieses Trikot die Seele des Teams symbolisiert.","The players explained patiently to him that this jersey symbolized the soul of the team."],["Der Trainer lächelte verständnisvoll und beschloss, die Tradition trotz des seltsamen Geruchs beizubehalten.","The coach smiled understandingly and decided to keep the tradition despite the odd smell."]],"v":[["hatte gewonnen","Plusquamperfekt","Past perfect formed with auxiliary hatte + participle gewonnen, indicating prior past event."],["trug","Präteritum","Irregular past tense of strong verb tragen (tragen -> trug -> getragen)."],["wurde","Präteritum","Irregular past tense of werden (to become)."],["in die Waschmaschine stecken","Akkusativ","Two-way preposition in indicating direction/placement (Wohin? -> fem. accusative die)."],["blieb","Präteritum","Irregular past of bleiben (bleiben -> blieb -> ist geblieben)."],["wurde aufbewahrt","Präteritum Passiv","Passive voice using wurde + participle II aufbewahrt."],["damit sie Glück hatten","","Final clause conjunction damit (so that / in order that) demands finite verb at the end."],["haben sich gewundert über","Reflexiv + Dativ/Akkusativ","Reflexive verb sich wundern takes preposition über + accusative."],["hat übernommen","Perfekt, untrennbar","Prefix über- in this context is inseparable, so no -ge- appears (übernommen)."],["beschloss beizubehalten","Infinitiv mit zu","Infinitival construction: separable verb beibehalten incorporates zu between prefix and stem (bei-zu-behalten)."]],"qs":[{"q":"Warum wusch niemand das rote Vereinstrikot?","o":["Das Trikot war aus empfindlicher Seide gefertigt.","Das Team glaubte, dass das ungewaschene Trikot Glück bringt.","Die Waschmaschine im Clubhaus war seit Jahren kaputt.","Der Verein hatte kein Geld für Waschmittel."],"a":1,"e":"Im Text heißt es: „Weil die Mannschaft nach dem Sieg sehr abergläubisch wurde, durfte die Zeugwartin das Trikot niemals in die Waschmaschine stecken.“"},{"q":"Was mussten die Spieler vor jedem Meisterschaftsspiel tun?","o":["Eine Runde um das gesamte Spielfeld laufen.","Ein lautes Lied in der Kabine singen.","Das rote Trikot mit der rechten Hand berühren.","Dem Trainer die Hände schütteln."],"a":2,"e":"Das feste Ritual lautete: „Vor jedem Meisterschaftsspiel mussten alle Spieler das Trikot mit der rechten Hand berühren ...“"},{"q":"Wie reagierte der neue Trainer zuerst auf das Trikot?","o":["Er warf es sofort in den Müll.","Er wunderte sich und fragte nach dem Grund für das schmutzige Hemd.","Er verbot den Spielern, die Vitrine zu öffnen.","Er zog das Trikot selbst sofort an."],"a":1,"e":"Der Trainer war überrascht: „Als er die alte Vitrine sah, fragte er erstaunt, warum das schmutzige Hemd dort hing.“"},{"q":"Was beschloss der Trainer nach der Erklärung der Spieler?","o":["Er wollte das Trikot heimlich in die Reinigung bringen.","Er verließ den Verein noch am selben Abend.","Er entschied sich dafür, das Ritual fortzusetzen.","Er ersetzte das alte Trikot durch einen neuen Pokal."],"a":2,"e":"Trotz des Geruchs akzeptierte er den Brauch: „Der Trainer lächelte verständnisvoll und beschloss, die Tradition ... beizubehalten.“"}],"_src":"Sports & Superstition (Inklingo Series)"},{"id":"A2-6","t":"Ein Wochenende im Schwarzwald ohne Empfang","l":"A2","cat":"Nature, Hiking & Camping (Original A2 Graded Reader)","pron":"Practice consonant blends: Schwarzwald [ˈʃvaʁtsvalt], Empfang [ɛmˈpfaŋ]. Notice the difference between /f/ and the /pf/ affricate in Empfang and Pfade.","e":"🌲","min":1,"s":[["Lena und Felix wollten dem stressigen Großstadtleben für zwei Tage entfliehen, weshalb sie eine Holzhütte im Schwarzwald mieteten.","Lena and Felix wanted to escape stressful city life for two days, which is why they rented a wooden cabin in the Black Forest."],["Schon bei der Ankunft stellten sie fest, dass ihre Mobiltelefone überhaupt kein Netz empfingen.","Already upon arrival, they determined that their mobile phones received no network at all."],["Zuerst erschraken sie ein wenig, aber dann haben sie sich schnell an die Ruhe gewöhnt.","At first, they were a bit startled, but then they quickly grew accustomed to the tranquility."],["Am Samstagmorgen schnürten sie ihre festen Wanderschuhe und brachen zu einer langen Tour auf den Feldberg auf.","On Saturday morning, they laced up their sturdy hiking boots and set off on a long tour up the Feldberg."],["Felix hatte eine Papierkarte in den Rucksack gesteckt, damit sie sich im dichten Nadelwald nicht verirren.","Felix had put a paper map into his backpack so that they would not get lost in the dense coniferous forest."],["Unterwegs begegneten sie kaum anderen Menschen, dafür hörten sie das laute Rauschen der Bergbäche.","On the way, they encountered hardly any other people, but instead heard the loud rushing of the mountain streams."],["Als dichter Nebel aufzog, mussten sie aufmerksam den markierten Pfaden folgen.","When thick fog rolled in, they had to follow the marked trails attentively."],["Lena hat sich darüber gefreut, wie frisch und würzig die feuchte Waldluft roch.","Lena was delighted by how fresh and aromatic the damp forest air smelled."],["Am Abend machten sie ein wärmendes Feuer im Kamin und lasen dicke Bücher.","In the evening, they made a warming fire in the fireplace and read thick books."],["Sie haben am Ende des Urlaubs bemerkt, dass das Leben ohne ständige Nachrichten viel erholsamer ist.","At the end of the holiday, they noticed that life without constant news is far more restful."]],"v":[["wollten entfliehen","Modalverb mit Infinitiv","Modal verb wollten governing dynamic infinitive entfliehen (to escape/flee from)."],["weshalb sie mieteten","","Conjunction weshalb (which is why / therefore) acts as subordinating conjunction placing verb mieteten at clause end."],["stellten fest","Präteritum, trennbar","From feststellen (to notice/determine/realize)."],["empfingen","Präteritum","Irregular strong verb empfangen (to receive) -> empfingen."],["haben sich gewöhnt an","Reflexiv + Präposition","Sich gewöhnen an takes accusative (an die Ruhe)."],["in den Rucksack gesteckt","Akkusativ","Two-way preposition in with masculine accusative (den Rucksack) showing direction of placement."],["damit sie sich ... nicht verirren","","Conjunction damit introducing purpose clause with reflexive verb sich verirren (to lose one's way)."],["begegneten","Präteritum mit Dativ","The verb begegnen (to meet/encounter) strictly governs the dative case (anderen Menschen)."],["als dichter Nebel aufzog","","Temporal subordinate clause introduced by als (when/as - single past event)."],["haben bemerkt, dass ... ist","","Perfekt of weak verb bemerken introducing dass-clause with verb ist at the end."]],"qs":[{"q":"Warum fuhren Lena und Felix in den Schwarzwald?","o":["Sie besuchten ein Musikfestival.","Sie wollten sich vom stressigen Stadtleben erholen.","Felix wollte dort beruflich ein Haus bauen.","Sie kauften ein neues Navigationsgerät."],"a":1,"e":"Der Einleitungssatz benennt das Motiv: „Lena und Felix wollten dem stressigen Großstadtleben für zwei Tage entfliehen ...“"},{"q":"Was passierte direkt nach ihrer Ankunft an der Hütte?","o":["Die Hütte war abgeschlossen und der Schlüssel fehlte.","Sie stellten fest, dass ihre Telefone kein Mobilfunknetz hatten.","Ein schweres Gewitter zerstörte das Hüttendach.","Felix verlor seine Brieftasche im Wald."],"a":1,"e":"Die Gegebenheit vor Ort: „Schon bei der Ankunft stellten sie fest, dass ihre Mobiltelefone überhaupt kein Netz empfingen.“"},{"q":"Wie schützten sich die beiden davor, sich im Wald zu verlaufen?","o":["Sie nutzten das GPS-System auf der Smartwatch.","Sie folgten einem einheimischen Bergführer.","Sie steckten eine traditionelle Papierkarte ein und folgten Pfadmarkierungen.","Sie blieben immer in der Nähe der Autostraße."],"a":2,"e":"Sicherheitsmaßnahme: „Felix hatte eine Papierkarte in den Rucksack gesteckt, damit sie sich im dichten Nadelwald nicht verirren.“"},{"q":"Welche Erkenntnis hatten die beiden am Ende des Ausflugs?","o":["Camping ist ihnen viel zu anstrengend und kalt.","Das Leben ohne ständige Erreichbarkeit und Medien ist entspannend.","Sie wollen nie wieder ohne Fernseher verreisen.","Der Schwarzwald ist für Anfänger zu gefährlich."],"a":1,"e":"Das Gesamtresümee am Textende: „Sie haben am Ende des Urlaubs bemerkt, dass das Leben ohne ständige Nachrichten viel erholsamer ist.“"}]},{"id":"A2-7","t":"Sport-Vereine haben so viele Mitglieder wie noch nie","l":"A2","cat":"Sports & German Society (Nachrichtenleicht Report)","pron":"Read compound nouns with deliberate pauses between roots: Sport-ver-ei-ne [ˈʃpɔʁtfɛɐ̯ˌʔaɪ̯nə], Mit-glie-der-zahl [ˈmɪtɡliːdɐˌtsaːl]. The ending -ung (Bewegung) must not have a hard /k/ sound: [bəˈveːɡʊŋ].","e":"🏅","min":1,"s":[["In Deutschland sind Sportvereine seit vielen Jahrzehnten ein wichtiger Teil der Gesellschaft.","In Germany, sports clubs have been an important part of society for many decades."],["Gestern hat der Deutsche Olympische Sportbund offizielle Zahlen vorgestellt, die viele Experten überraschten.","Yesterday, the German Olympic Sports Confederation presented official figures that surprised many experts."],["Die Vereine haben aktuell so viele Mitglieder wie noch nie zuvor in ihrer Geschichte.","Currently, the clubs have as many members as never before in their history."],["Besonders bei kleinen Kindern und älteren Menschen ist die Nachfrage nach Vereinssport stark gestiegen.","Particularly among young children and elderly people, demand for club sports has risen sharply."],["Viele Menschen haben während der langen Pandemie gemerkt, dass ihnen gemeinsame Bewegung im Alltag fehlt.","Many people noticed during the long pandemic that they lacked collective exercise in everyday life."],["Im Sportverein kann man nicht nur fit bleiben, sondern man schließt auch neue Freundschaften.","In a sports club, one can not only stay fit, but one also forms new friendships."],["Ein Sprecher erklärte im Radio, dass Fußball und Turnen weiterhin die beliebtesten Sportarten bleiben.","A spokesperson explained on the radio that football and gymnastics continue to remain the most popular types of sport."],["Viele ehrenamtliche Trainer helfen jede Woche auf den Sportplätzen, obwohl sie dafür kein Geld bekommen.","Many volunteer trainers help on sports grounds every week, although they receive no money for it."],["Ohne diese freiwilligen Helfer könnten die Vereine ihre günstigen Kurse kaum anbieten.","Without these voluntary helpers, the clubs could hardly offer their affordable courses."],["Die Regierung will die Vereine nun mit zusätzlichen Fördergeldern unterstützen, damit Hallen renoviert werden können.","The government now wants to support the clubs with additional subsidies so that sports halls can be renovated."]],"v":[["hat vorgestellt","Perfekt, trennbar","Vorstellen (to present/introduce) -> hat vorgestellt."],["ist gestiegen","Perfekt mit sein","Verb of movement/change of state (steigen) strictly demands auxiliary sein."],["dass ihnen Bewegung fehlt","Dativobjekt","Impersonal structure with fehlen: the thing missed is the subject (Bewegung), the experiencer takes dative (ihnen)."],["nicht nur ..., sondern auch","Doppelkonjunktion","Multi-part connector meaning \"not only ..., but also ...\"."],["schließt Freundschaften","Kollokation","Fixed expression Freundschaften schließen (to form friendships / make friends)."],["obwohl sie kein Geld bekommen","","Concessive conjunction obwohl (although) pushes the finite verb bekommen to the clause end."],["ehrenamtlich","Adjektiv","Honorary / voluntary unpaid work, a fundamental concept in German community life (Vereinsleben)."],["könnten anbieten","Konjunktiv II","Subjunctive modal könnten used for hypothetical condition (Without helpers, they could hardly...)."],["will unterstützen","Modalverb","Regular present tense of wollen (er/sie/es will) + terminal infinitive."],["damit Hallen renoviert werden können","Passiv mit Modalverb","Purpose clause featuring passive infinitive (renoviert werden) combined with modal auxiliary (können)."]],"qs":[{"q":"Was gab der Deutsche Olympische Sportbund kürzlich bekannt?","o":["Dass viele Sportvereine für immer schließen müssen.","Dass die Mitgliederzahlen einen historischen Höchststand erreicht haben.","Dass Sportvereine in Zukunft nur noch für Profisportler da sind.","Dass alle Sportplätze in Parks umgewandelt werden."],"a":1,"e":"Der Bericht vermeldet: „Die Vereine haben aktuell so viele Mitglieder wie noch nie zuvor in ihrer Geschichte.“"},{"q":"Welche Gruppen traten den Vereinen zuletzt besonders häufig bei?","o":["Junge Erwachsene und Leistungssportler.","Ausländische Touristen und Studenten.","Kleine Kinder und ältere Menschen.","Ausschließlich professionelle Fußballspieler."],"a":2,"e":"Spezifizierung im Text: „Besonders bei kleinen Kindern und älteren Menschen ist die Nachfrage nach Vereinssport stark gestiegen.“"},{"q":"Warum engagieren sich ehrenamtliche Trainer in den Vereinen?","o":["Weil sie sehr hohe monatliche Gehälter erhalten.","Weil sie freiwillig helfen, obwohl sie keine Bezahlung bekommen.","Weil sie vom Staat dazu gezwungen werden.","Weil sie die Vereine aufkaufen möchten."],"a":1,"e":"Die Definition der Ehrenamtlichkeit: „Viele ehrenamtliche Trainer helfen jede Woche auf den Sportplätzen, obwohl sie dafür kein Geld bekommen.“"},{"q":"Wofür will die Regierung den Sportvereinen finanzielle Mittel bereitstellen?","o":["Für teure Werbekampagnen im Fernsehen.","Für die Renovierung und Modernisierung von Sporthallen.","Für Urlaubsreisen der Vereinsfunktionäre.","Für den Kauf von teuren Dienstwagen."],"a":1,"e":"Zur staatlichen Unterstützung: „Die Regierung will die Vereine nun mit zusätzlichen Fördergeldern unterstützen, damit Hallen renoviert werden können.“"}]},{"id":"A2-8","t":"Der kleine Unfall mit dem Roller im Regen","l":"A2","cat":"Daily Transport & Mechanics (Original A2 Graded Reader)","pron":"Watch the diphthongs: Reifen [ˈʁaɪ̯fn̩], schlecht [ʃlɛçt]. Distinguish the voiceless ch [ç] in Bremsen and vorsichtig [ˈfoːɐ̯zɪçtɪç] from the velar ach-sound.","e":"🚲","min":1,"s":[["Gestern Nachmittag regnete es in Hamburg ununterbrochen, und der Asphalt war spiegelglatt.","Yesterday afternoon it rained continuously in Hamburg, and the asphalt was slippery as ice."],["Tim wollte trotzdem mit seinem neuen Elektroroller zum Supermarkt fahren, weil er dringend Lebensmittel brauchte.","Tim nevertheless wanted to ride his new electric scooter to the supermarket because he urgently needed groceries."],["Seine Mitbewohnerin warnte ihn noch, dass er bei diesem nassen Wetter besonders vorsichtig fahren müsse.","His flatmate warned him beforehand that he must drive particularly carefully in this wet weather."],["Tim setzte seinen Schutzhelm auf und bog an der ersten Kreuzung zügig nach links ab.","Tim put on his protective helmet and turned swiftly to the left at the first intersection."],["Auf den nassen Straßenbahnschienen verlor das Vorderrad plötzlich die Haftung, und der Roller rutschte weg.","On the wet tram tracks, the front wheel suddenly lost grip, and the scooter slipped away."],["Tim stürzte unsanft auf den nassen Bürgersteig, aber er hat sich glücklicherweise nicht schwer verletzt.","Tim fell roughly onto the wet pavement, but fortunately he did not injure himself seriously."],["Eine ältere Passantin kam sofort herbeigelaufen und fragte erschrocken, ob sie einen Krankenwagen rufen solle.","An elderly female pedestrian immediately came running over and asked in fright whether she should call an ambulance."],["Tim bedankte sich höflich bei der Dame und erklärte, dass er nur ein paar Schrammen am Knie hatte.","Tim thanked the lady politely and explained that he only had a few scrapes on his knee."],["Der Roller hatte jedoch einen platten Reifen und ein kaputtes Schutzblech.","The scooter, however, had a flat tire and a broken mudguard."],["Tim hat das defekte Fahrzeug den ganzen Weg nach Hause geschoben und daraus gelernt, bei Regen lieber die U-Bahn zu nehmen.","Tim pushed the defective vehicle all the way home and learned from this to rather take the underground when it rains."]],"v":[["regnete","Impersonales Verb, Präteritum","Impersonal weather expression es regnet -> past tense es regnete."],["spiegelglatt","Zusammengesetztes Adjektiv","Compound adjective: Spiegel (mirror) + glatt (slippery/smooth) = as slippery as ice."],["warnte, dass ... müsse","Konjunktiv I in der indirekten Rede","Subordinate clause reporting advice using subjunctive form müsse."],["setzte auf","Präteritum, trennbar","Aufsetzen (to put on headgear/glasses)."],["bog ... ab","Präteritum, trennbar","Strong verb abbiegen (bog ab, ist abgebogen)."],["auf den Straßenbahnschienen","Dativ Plural","Two-way preposition auf with dative plural (den Schienen + n ending)."],["rutschte weg","Präteritum, schwach","Verb wegrutschen describing accidental sideways movement."],["hat sich verletzt","Reflexiv Perfekt","Sich verletzen (to injure oneself). Takes accusative reflexive pronoun (sich)."],["ob sie ... rufen solle","Indirekte Frage","Subordinate clause introduced by ob with modal verb sollen at the clause end."],["hat geschoben","Perfekt","Strong verb schieben (to push) -> schob -> hat geschoben."]],"qs":[{"q":"Warum fuhr Tim trotz des starken Regens mit dem Roller los?","o":["Er hatte einen wichtigen Termin beim Arzt.","Er wollte eine Freundin vom Bahnhof abholen.","Er musste dringend Einkäufe im Supermarkt erledigen.","Er wollte seinen neuen Regenmantel testen."],"a":2,"e":"Grund für den Ausflug: „... weil er dringend Lebensmittel brauchte.“"},{"q":"Was verursachte den Sturz auf der Straße?","o":["Eine rote Ampel, die er übersehen hatte.","Das Vorderrad rutschte auf nassen Straßenbahnschienen ab.","Ein Fußgänger trat plötzlich auf den Radweg.","Die Bremse des Rollers funktionierte gar nicht."],"a":1,"e":"Auslöser des Unfalls: „Auf den nassen Straßenbahnschienen verlor das Vorderrad plötzlich die Haftung, und der Roller rutschte weg.“"},{"q":"Wie verhielt sich die Passantin nach dem Vorfall?","o":["Sie rief sofort die Polizei und schimpfte laut.","Sie lief zu ihm und bot an, einen Notarzt zu rufen.","Sie ging einfach weiter, ohne anzuhalten.","Sie half ihm, den kaputten Reifen aufzupumpen."],"a":1,"e":"Hilfsbereitschaft der Zeugin: „Eine ältere Passantin kam sofort herbeigelaufen und fragte erschrocken, ob sie einen Krankenwagen rufen solle.“"},{"q":"Wie transportierte Tim seinen Roller zurück nach Hause?","o":["Er lud ihn in den Kofferraum eines Taxis.","Er fuhr trotz des Schadens langsam weiter.","Er schob das beschädigte Gefährt zu Fuß nach Hause.","Er ließ den Roller an der Unfallstelle stehen."],"a":2,"e":"Rückweg: „Tim hat das defekte Fahrzeug den ganzen Weg nach Hause geschoben ...“"}]},{"id":"A2-9","t":"Das Paket für den Nachbarn im dritten Stock","l":"A2","cat":"Neighborhood & Communication (Original A2 Graded Reader)","pron":"Distinct pronunciation of prefix sounds: über-geben [yːbɐˈɡeːbn̩] vs. ab-geben [ˈapˌɡeːbn̩]. Notice the long vowel /eː/ in Paket [paˈkeːt] and the cluster /k/ in Paketbote [paˈkeːtˌboːtə].","e":"📦","min":1,"s":[["Gestern Vormittag klingelte der Paketbote mehrmals stürmisch an Annas Wohnungstür im Erdgeschoss.","Yesterday morning, the parcel courier rang tempestuously several times at Anna’s apartment door on the ground floor."],["Er hielt ein großes, schweres Paket in beiden Armen und fragte gehetzt, ob sie die Sendung für Herrn Weber annehmen könne.","He held a large, heavy parcel in both arms and asked hurriedly whether she could accept the delivery for Mr. Weber."],["Da Herr Weber im dritten Stock wohnt und tagsüber im Büro arbeitet, hat Anna hilfsbereit zugestimmt.","Since Mr. Weber lives on the third floor and works at the office during the day, Anna helpfully agreed."],["Sie stellte den unhandlichen Karton in ihren schmalen Flur direkt neben das Schuhregal.","She placed the unwieldy cardboard box in her narrow hallway right next to the shoe rack."],["Am frühen Abend hat Anna an Herrn Webers Tür geklopft, aber niemand öffnete.","In the early evening, Anna knocked on Mr. Weber’s door, but nobody answered."],["Sie hat sich schon Sorgen gemacht, weil Herr Weber seine Pakete normalerweise pünktlich abholt.","She was already getting worried because Mr. Weber usually picks up his parcels punctually."],["Deshalb schrieb sie einen kurzen, freundlichen Zettel und klebte ihn an seine Wohnungstür.","Therefore, she wrote a short, friendly note and taped it to his apartment door."],["Zwei Stunden später klingelte Herr Weber schließlich an Annas Tür und bedankte sich überschwänglich für ihre Unterstützung.","Two hours later, Mr. Weber finally rang Anna’s bell and thanked her profusely for her support."],["Er erklärte mit einem Lächeln, dass sein Zug Verspätung hatte und er deshalb erst spät nach Hause kam.","He explained with a smile that his train had been delayed and he had therefore arrived home late."],["Als Dankeschön schenkte er Anna eine Schachtel Pralinen, was sie sehr gefreut hat.","As a thank-you, he gave Anna a box of chocolates, which made her very happy."]],"v":[["klingelte an der Wohnungstür","Dativ","Weak verb klingeln with preposition an + dative (der Wohnungstür)."],["ob sie ... annehmen könne","Indirekte Rede","Dependent clause with conjunction ob and subjunctive modal könne."],["da Herr Weber ... wohnt","Kausalsatz","Subordinating conjunction da (synonym for weil, more formal) places the verb wohnt at the end."],["hat zugestimmt","Perfekt, trennbar","Strong verb zustimmen (to agree/consent) takes dative: hat zugestimmt."],["stellte neben das Schuhregal","Akkusativ","Directional action (Wohin?) requiring two-way preposition neben + neuter accusative (das Regal)."],["hat sich Sorgen gemacht","Feste Wendung, Reflexiv","Sich Sorgen machen (to worry)."],["klebte an seine Wohnungstür","Akkusativ","Directional placement (Wohin klebte sie ihn?) -> an + feminine accusative seine Tür."],["bedankte sich für","Reflexiv + Präposition","Sich bedanken bei [Dativ] für [Akkusativ] (to thank someone for something)."],["dass sein Zug Verspätung hatte","","Subordinating conjunction dass with verb hatte at the end."],["was sie sehr gefreut hat","Relativsatz mit 'was'","Indefinite relative pronoun was referring back to the entire preceding action."]],"qs":[{"q":"Was wollte der Paketbote von Anna?","o":["Er suchte nach dem Hausmeister des Gebäudes.","Sie sollte ein Paket für einen Nachbarn entgegennehmen.","Sie sollte eine Quittung für Reparaturarbeiten unterschreiben.","Er wollte ihr ein persönliches Geschenk überreichen."],"a":1,"e":"Der Paketbote fragte Anna: „... ob sie die Sendung für Herrn Weber annehmen könne.“"},{"q":"Wohin legte Anna das Paket nach der Annahme?","o":["In das Treppenhaus vor die Haustür.","In ihren Flur neben das Regal für Schuhe.","Direkt auf den Küchentisch.","In den Keller des Mietshauses."],"a":1,"e":"Positionierung des Pakets: „Sie stellte den unhandlichen Karton in ihren schmalen Flur direkt neben das Schuhregal.“"},{"q":"Wie informierte Anna Herrn Weber über das Paket?","o":["Sie schickte ihm eine E-Mail über das Smartphone.","Sie rief seinen Chef im Büro an.","Sie befestigte eine kurze Notiz an seiner Eingangstür.","Sie wartete mehrere Stunden im Flur auf ihn."],"a":2,"e":"Kommunikationsmittel: „Deshalb schrieb sie einen kurzen, freundlichen Zettel und klebte ihn an seine Wohnungstür.“"},{"q":"Warum kam Herr Weber erst so spät an diesem Abend nach Hause?","o":["Er musste im Büro unbezahlte Überstunden machen.","Er hatte einen kleinen Unfall auf der Autobahn.","Sein Zug hatte eine deutliche Verspätung.","Er hatte den Schlüssel für seine Wohnung verloren."],"a":2,"e":"Grund für die Verzögerung: „Er erklärte mit einem Lächeln, dass sein Zug Verspätung hatte und er deshalb erst spät nach Hause kam.“"}]},{"id":"A2-10","t":"Die Nachtschicht im Kundenservice","l":"A2","cat":"Work, Problem Solving & Patience (Original A2 Graded Reader)","pron":"Note the consonant cluster nd in Kundenservice [ˈkʊndn̩ˌsœːɐ̯vɪs]. Emphasize prefixes properly: beantworten [bəˈʔantvɔʁtn̩], ausschalten [ˈaʊ̯sˌʃaltn̩].","e":"🌙","min":1,"s":[["Sebastian arbeitet dreimal pro Woche in der Nachtschicht bei einem großen Internetanbieter in Leipzig.","Sebastian works the night shift three times a week at a large internet service provider in Leipzig."],["Gestern Nacht war es im modernen Büro ungewöhnlich ruhig, weil nur wenige Kunden anriefen.","Last night it was unusually quiet in the modern office because only a few customers called."],["Gegen drei Uhr morgens hat plötzlich ein sehr wütender Mann angerufen, dessen Internetverbindung komplett ausgefallen war.","Towards three o’clock in the morning, a very furious man suddenly phoned whose internet connection had failed completely."],["Der Kunde schimpfte lautstark am Telefon und behauptete, dass die Firma absichtlich seinen Anschluss sabotiert habe.","The customer ranted loudly on the phone and claimed that the company had deliberately sabotaged his connection."],["Sebastian blieb vollkommen ruhig und hörte dem aufgeregten Kunden zuerst geduldig zu.","Sebastian remained completely calm and listened patiently to the agitated customer first."],["Danach hat er den Mann höflich gebeten, dass er den Router für dreißig Sekunden ausschalten und dann neu starten solle.","Afterwards, he politely asked the man to switch off the router for thirty seconds and then restart it."],["Der Mann befolgte die Anweisung widerwillig, während Sebastian die Serverdaten auf seinem Monitor überprüfte.","The man followed the instruction reluctantly while Sebastian checked the server data on his monitor."],["Nach zwei Minuten leuchteten die kleinen Kontrolllampen am Router des Kunden wieder grün.","After two minutes, the small indicator lights on the customer’s router lit up green again."],["Der Mann hat sich aufrichtig für seinen unhöflichen Ton entschuldigt, weil er sehr erleichtert war.","The man apologized sincerely for his rude tone because he was very relieved."],["Sebastian lächelte müde und wünschte ihm eine gute Nacht, bevor er das Gespräch beendete.","Sebastian smiled tiredly and wished him a good night before he ended the call."]],"v":[["in der Nachtschicht","Dativ","Feminine noun die Nachtschicht in static local context (Wo arbeitet er?) with preposition in -> in der Nachtschicht."],["riefen an","Präteritum, trennbar","From strong separable verb anrufen (rief an, hat angerufen)."],["dessen Internetverbindung","Relativpronomen Genitiv","Masculine genitive relative pronoun dessen (whose), linking back to ein Mann."],["schimpfte / behauptete","Präteritum","Regular past tense verbs forming narrative background."],["blieb ruhig","Kopulaverb","Strong verb bleiben links subject with predicate adjective without case inflection."],["hörte zu","Präteritum, trennbar","Strong verb zuhören (to listen to someone attentively) governs the dative case (dem Kunden)."],["hat gebeten","Perfekt","Irregular strong verb bitten (to ask/request): bitten -> bat -> gebeten."],["während Sebastian ... überprüfte","Temporalsatz","Subordinating conjunction während (while) keeps finite verb überprüfte at the very end."],["hat sich entschuldigt für","Reflexiv Perfekt","Sich entschuldigen bei [Dativ] für [Akkusativ]."],["bevor er das Gespräch beendete","Temporalsatz","Subordinating temporal conjunction bevor (before) placing beendete at the sentence terminus."]],"qs":[{"q":"Zu welcher Tageszeit arbeitet Sebastian bei dem Telekommunikationsunternehmen?","o":["Am frühen Morgen vor Sonnenaufgang.","Während der regulären Mittagszeit.","Während der ruhigen Nachtschicht.","Nur an Samstagnachmittagen."],"a":2,"e":"Die Arbeitszeit wird im ersten Satz genannt: „Sebastian arbeitet dreimal pro Woche in der Nachtschicht ...“"},{"q":"Warum rief der Kunde mitten in der Nacht so aufgebracht an?","o":["Seine Rechnung war viel höher als vereinbart.","Sein gesamter Internetanschluss funktionierte plötzlich nicht mehr.","Er wollte ein neues Mobiltelefon bestellen.","Sein Computer war von einem Virus befallen worden."],"a":1,"e":"Ursache des Anrufs: „... dessen Internetverbindung komplett ausgefallen war.“ Der Ausfall verärgerte den Kunden."},{"q":"Welchen technischen Ratschlag erteilte Sebastian dem Anrufer?","o":["Ein neues Netzwerkkabel im Fachgeschäft zu kaufen.","Den Internetrouter für eine halbe Minute vom Strom zu trennen und neu zu starten.","Den Computer sofort zu formatieren.","Bis zum nächsten Vormittag auf den Techniker zu warten."],"a":1,"e":"Sebastians Problemlösung: „Danach hat er den Mann höflich gebeten, dass er den Router für dreißig Sekunden ausschalten und dann neu starten solle.“"},{"q":"Wie verhielt sich der Kunde, nachdem das Internet wieder funktionierte?","o":["Er legte ohne ein Wort der Verabschiedung auf.","Er verlangte sofort den Vorgesetzten von Sebastian.","Er entschuldigte sich aufrichtig für sein vorheriges unhöfliches Verhalten.","Er kündigte fristlos seinen gesamten Vertrag."],"a":2,"e":"Die Reaktion nach geglückter Verbindung: „Der Mann hat sich aufrichtig für seinen unhöflichen Ton entschuldigt, weil er sehr erleichtert war.“"}]}]);
